export function getPhase104(phaseId: string): PhaseDossier104 | undefined {
  return CANONICAL_PHASE_DOSSIER_250x104[phaseId];
}

export function listPhases104(): PhaseDossier104[] {
  return Object.values(CANONICAL_PHASE_DOSSIER_250x104);
}

export function getPhaseSection104(phaseId: string, sectionKey: string): unknown {
  const phase = CANONICAL_PHASE_DOSSIER_250x104[phaseId] as any;
  return phase ? phase[sectionKey] : undefined;
}

export function verifyPhase104Invariants(phaseId: string): { valid: boolean; missingSections: string[] } {
  const phase = CANONICAL_PHASE_DOSSIER_250x104[phaseId] as any;
  if (!phase) return { valid: false, missingSections: ["PHASE_NOT_FOUND"] };

  const requiredSections = [
    "A_authority", "B_baseline", "C_contracts", "D_dependencies", "E_entry", "F_failure",
    "G_governance", "H_humanControl", "I_integration", "J_journey", "K_context", "L_lineage",
    "M_metrics", "N_navigation", "O_observability", "P_persistence", "Q_retrieval", "R_response",
    "S_security", "T_testing", "U_uncertainty", "V_verification", "W_workflow", "X_experience",
    "Y_yield", "Z_exit",
    "a_persona", "b_session", "c_history", "d_segmentation", "e_timeline", "f_multimodal",
    "g_numeric", "h_promptLineage", "i_oldChatRetrieval", "j_ranking", "k_memoryAdmission",
    "l_memoryExpiry", "m_sourceDiscovery", "n_sourceAuthority", "o_citations", "p_safeReasoning",
    "q_questionTaxonomy", "r_intent", "s_answerPlan", "t_specialistRouting", "u_toolRouting",
    "v_approval", "w_toolEvidence", "x_answerVerification", "y_summary", "z_nextStage",
    "AA_refA", "AB_refB", "AC_refC", "AD_refD", "AE_refE", "AF_refF", "AG_refG", "AH_refH",
    "AI_refI", "AJ_refJ", "AK_refK", "AL_refL", "AM_refM", "AN_refN", "AO_refO", "AP_refP",
    "AQ_refQ", "AR_refR", "AS_refS", "AT_refT", "AU_refU", "AV_refV", "AW_refW", "AX_refX",
    "AY_refY", "AZ_refZ",
    "aa_refa", "ab_refb", "ac_refc", "ad_refd", "ae_refe", "af_reff", "ag_refg", "ah_refh",
    "ai_refi", "aj_refj", "ak_refk", "al_refl", "am_refm", "an_refn", "ao_refo", "ap_refp",
    "aq_refq", "ar_refr", "as_refs", "at_reft", "au_refu", "av_refv", "aw_refw", "ax_refx",
    "ay_refy", "az_refz"
  ];

  const missing = requiredSections.filter((s) => phase[s] === undefined);
  return { valid: missing.length === 0, missingSections: missing };
}